class Student:
    def __init__(self, name, score):
        self.name = name
        self.score = score

    def __lt__(self, other):
        return self.score < other.score

    def __repr__(self):
        return f"Student({self.name!r}, {self.score})"

students = [Student("ana", 90), Student("bo", 72), Student("cy", 85)]
print(sorted(students))

independent.solution:
class Report:
    def __init__(self, title):
        self.title = title

    def render(self):
        return f"== {self.title} =="

class SalesReport(Report):
    def __init__(self, title, rows):
        super().__init__(title)
        self.rows = rows

    def render(self):
        lines = [super().render()]
        for region, amount in self.rows:
            lines.append(f"{region}: {amount:.2f}")
        lines.append(f"Total: {sum(a for _, a in self.rows):.2f}")
        return "\n".join(lines)

print(SalesReport("Q1", [("North", 100), ("South", 50.5)]).render())
print(Report("Plain").render())

class Shape:
    def area(self):
        return 0

    def __lt__(self, other):
        return self.area() < other.area()

class Rect(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h

    def area(self):
        return self.w * self.h

class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return 3.14159 * self.r ** 2

class Drawing:
    def __init__(self):
        self.shapes = []

    def add(self, shape):
        self.shapes.append(shape)

    def total_area(self):
        return sum(s.area() for s in self.shapes)

    def largest(self):
        return max(self.shapes, key=lambda s: s.area())

d = Drawing()
for s in (Rect(2, 3), Circle(1), Rect(1, 1)):
    d.add(s)
print(f"Total: {d.total_area():.2f}")
print(type(d.largest()).__name__)
print([round(s.area(), 2) for s in sorted(d.shapes)])

